using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Muchi.Net;

namespace Muchi.Client
{
    // Round 9 gacha live-ops on the wire (contracts/protocol.md §17, server/src/domain/gacha.ts, REQ-GACHA-011..015).
    // Every number and text here is generated by the server from the drawing tables and the schedule: display verbatim.

    /// <summary>The featured horse of a banner (its rate is on the odds page, never on the banner).</summary>
    public sealed class BannerPickup
    {
        public string TemplateId, Name, Rarity;
        internal static BannerPickup Parse(JsonNode o) => o == null ? null : new BannerPickup { TemplateId = J.Str(o, "templateId"), Name = J.Str(o, "name"), Rarity = J.Str(o, "rarity") };
    }

    /// <summary>Step-up shape on the banner list: the 10-pull price of each step and the steps whose slot 10 has its own table.</summary>
    public sealed class BannerStepUp
    {
        public int Steps;
        /// <summary>"loop" (back to step 1) or "repeatLast".</summary>
        public string AfterLast;
        public int[] Prices = new int[0];
        public int[] FinalSlotSteps = new int[0];
        internal static BannerStepUp Parse(JsonNode o) => o == null ? null : new BannerStepUp
        {
            Steps = J.Int(o, "steps"), AfterLast = J.Str(o, "afterLast"), Prices = J.Ints(o, "prices"), FinalSlotSteps = J.Ints(o, "finalSlotSteps"),
        };
    }

    /// <summary>GET /v1/gacha/banners: active and announced banners in display order, with the server clock (REQ-GACHA-011).</summary>
    public sealed class BannerSchedule
    {
        /// <summary>Server time when the list was built; count down against it, not the device clock.</summary>
        public long ServerNowMs;
        public List<Banner> Banners = new List<Banner>();
        internal static BannerSchedule Parse(JsonNode o) => new BannerSchedule { ServerNowMs = J.Long(o, "serverNowMs"), Banners = J.List(o, "banners", Banner.Parse) };
        public static BannerSchedule FromJson(string json) => Parse(JsonNode.Parse(json));
    }

    public sealed class PityTarget
    {
        public string TemplateId, Name;
        /// <summary>Already in the stable (exchanging it gives awakening material instead).</summary>
        public bool Owned;
        internal static PityTarget Parse(JsonNode o) => new PityTarget { TemplateId = J.Str(o, "templateId"), Name = J.Str(o, "name"), Owned = J.Bool(o, "owned") };
    }

    /// <summary>
    /// What happens to a limited group's points when it closes (REQ-GACHA-013): they move 1:1 into <see cref="ToGroup"/>,
    /// never expire, and can be exchanged there for <see cref="ToTargets"/> (a choice, not a draw). Show <see cref="Notice"/>.
    /// </summary>
    public sealed class CarryOverRule
    {
        public long AtMs;
        public string ToGroup, ToLabel, Rate, Notice;
        public bool Expires;
        public List<PityTarget> ToTargets = new List<PityTarget>();
        internal static CarryOverRule Parse(JsonNode o) => o == null ? null : new CarryOverRule
        {
            AtMs = J.Long(o, "atMs"), ToGroup = J.Str(o, "toGroup"), ToLabel = J.Str(o, "toLabel"), Rate = J.Str(o, "rate"), Notice = J.Str(o, "notice"),
            Expires = J.Bool(o, "expires"), ToTargets = J.List(o, "toTargets", PityTarget.Parse),
        };
    }

    /// <summary>Step-up progress: the step the next 10-pull is on (1-based) and its price.</summary>
    public sealed class StepUpProgress
    {
        public int Completed, Steps, Step, Round, PriceTen;
        public string AfterLast;
        /// <summary>Slot 10 of this step is always drawn from its own table, at least this rarity ("SSR"); null: the usual SR+ guarantee.</summary>
        public string FinalSlotMinRarity;
        internal static StepUpProgress Parse(JsonNode o) => o == null ? null : new StepUpProgress
        {
            Completed = J.Int(o, "completed"), Steps = J.Int(o, "steps"), Step = J.Int(o, "step"), Round = J.Int(o, "round", 1), PriceTen = J.Int(o, "priceTen"),
            AfterLast = J.Str(o, "afterLast"), FinalSlotMinRarity = J.Str(o, "finalSlotMinRarity"),
        };
    }

    /// <summary>One pity group of the player (REQ-GACHA-012).</summary>
    public sealed class PityGroupStatus
    {
        public string Group, Label;
        public int Points, Cost, Remaining;
        /// <summary>Exchanges possible right now (0 when no banner of the group is open).</summary>
        public int Exchangeable;
        public string[] Banners = new string[0];
        public List<PityTarget> Targets = new List<PityTarget>();
        /// <summary>When the group closes (null: never).</summary>
        public long? ClosesAtMs;
        public CarryOverRule CarryOver;
        internal static PityGroupStatus Parse(JsonNode o) => new PityGroupStatus
        {
            Group = J.Str(o, "group"), Label = J.Str(o, "label"), Points = J.Int(o, "points"), Cost = J.Int(o, "cost"), Remaining = J.Int(o, "remaining"),
            Exchangeable = J.Int(o, "exchangeable"), Banners = J.Strs(o, "banners"), Targets = J.List(o, "targets", PityTarget.Parse),
            ClosesAtMs = J.LongN(o, "closesAtMs"), CarryOver = CarryOverRule.Parse(J.Opt(o, "carryOver")),
        };
    }

    /// <summary>The pity meter of one open banner: pulls and coins still needed (step prices on a step-up).</summary>
    public sealed class BannerPityStatus
    {
        public string BannerId, PityGroup;
        public int Points, Cost, Remaining, CoinsToExchange;
        public StepUpProgress StepUp;
        internal static BannerPityStatus Parse(JsonNode o) => new BannerPityStatus
        {
            BannerId = J.Str(o, "bannerId"), PityGroup = J.Str(o, "pityGroup"), Points = J.Int(o, "points"), Cost = J.Int(o, "cost"),
            Remaining = J.Int(o, "remaining"), CoinsToExchange = J.Int(o, "coinsToExchange"), StepUp = StepUpProgress.Parse(J.Opt(o, "stepUp")),
        };
    }

    /// <summary>GET /v1/gacha/status (player): the pity meter, carry-over rules and step-up progress.</summary>
    public sealed class GachaStatus
    {
        public long ServerNowMs;
        public List<PityGroupStatus> Groups = new List<PityGroupStatus>();
        public List<BannerPityStatus> Banners = new List<BannerPityStatus>();
        public BannerPityStatus ForBanner(string bannerId) => Banners.Find(b => b.BannerId == bannerId);
        public PityGroupStatus ForGroup(string group) => Groups.Find(g => g.Group == group);
        internal static GachaStatus Parse(JsonNode o) => new GachaStatus
        {
            ServerNowMs = J.Long(o, "serverNowMs"), Groups = J.List(o, "groups", PityGroupStatus.Parse), Banners = J.List(o, "banners", BannerPityStatus.Parse),
        };
        public static GachaStatus FromJson(string json) => Parse(JsonNode.Parse(json));
    }

    /// <summary>The featured horse's own rate on the odds page (from the same rows as the table).</summary>
    public sealed class OddsPickup
    {
        public string TemplateId, Name, Rarity, Rate, GuaranteeRate;
        public int Ppm, GuaranteePpm;
        internal static OddsPickup Parse(JsonNode o) => o == null ? null : new OddsPickup
        {
            TemplateId = J.Str(o, "templateId"), Name = J.Str(o, "name"), Rarity = J.Str(o, "rarity"), Ppm = J.Int(o, "ppm"), Rate = J.Str(o, "rate"),
            GuaranteePpm = J.Int(o, "guaranteePpm"), GuaranteeRate = J.Str(o, "guaranteeRate"),
        };
    }

    /// <summary>One step of a step-up on the odds page: price and the slot-10 table (null items: the banner's SR+ guarantee table).</summary>
    public sealed class OddsStep
    {
        public int Step, PriceTen;
        public string FinalSlotAppliesTo;
        public List<OddsRow> FinalSlotItems;
        public Dictionary<string, RarityTotal> FinalSlotRarityTotals;
        internal static OddsStep Parse(JsonNode o)
        {
            var f = J.Opt(o, "finalSlot");
            var hasTable = J.Opt(f, "items") != null;
            return new OddsStep
            {
                Step = J.Int(o, "step"), PriceTen = J.Int(o, "priceTen"), FinalSlotAppliesTo = J.Str(f, "appliesTo"),
                FinalSlotItems = hasTable ? J.List(f, "items", OddsRow.Parse) : null,
                FinalSlotRarityTotals = hasTable ? J.Map(f, "rarityTotals", RarityTotal.Parse) : null,
            };
        }
    }

    public sealed class OddsStepUp
    {
        public string AfterLast, Notice;
        public List<OddsStep> Steps = new List<OddsStep>();
        internal static OddsStepUp Parse(JsonNode o) => o == null ? null : new OddsStepUp { AfterLast = J.Str(o, "afterLast"), Notice = J.Str(o, "notice"), Steps = J.List(o, "steps", OddsStep.Parse) };
    }

    /// <summary>Step-up part of a draw result: the step just drawn (1-based) and the next one.</summary>
    public sealed class DrawStepUp
    {
        public int DrawnStep;
        public StepUpProgress Next;
        internal static DrawStepUp Parse(JsonNode o) => o == null ? null : new DrawStepUp { DrawnStep = J.Int(o, "drawnStep"), Next = StepUpProgress.Parse(J.Opt(o, "next")) };
    }

    /// <summary>
    /// Quality pass 2 (server/src/domain/scoutOptions.ts, protocol 「スカウトの確認」): one way to pull on a banner now —
    /// coins (with the exact paid / free split, paid first) or a ticket the player holds. Read only; the pull itself is
    /// DrawAsync / UseTicketAsync, which decide again on the transaction.
    /// </summary>
    public sealed class ScoutWay
    {
        /// <summary>coins_1 | coins_10 | ticket:&lt;itemId&gt;</summary>
        public string Id, Via, ItemId, Label, Line;
        /// <summary>null when the player is short (or a ticket way).</summary>
        public int? Price, PaysPaid, PaysFree, AfterPaid, AfterFree, Owned, Shortfall;
        public int Count, PityGain;
        public bool Available;
        /// <summary>short | closed | upcoming | debt | null</summary>
        public string Block;
        internal static ScoutWay Parse(JsonNode o)
        {
            var pays = J.Opt(o, "pays"); var after = J.Opt(o, "after");
            return new ScoutWay
            {
                Id = J.Str(o, "id"), Via = J.Str(o, "via"), ItemId = J.Str(o, "itemId"), Label = J.Str(o, "label"), Line = J.Str(o, "line"),
                Count = J.Int(o, "count"), Price = J.IntN(o, "price"), Owned = J.IntN(o, "owned"), Shortfall = J.IntN(o, "shortfall"),
                PaysPaid = pays == null ? (int?)null : J.Int(pays, "paid"), PaysFree = pays == null ? (int?)null : J.Int(pays, "free"),
                AfterPaid = after == null ? (int?)null : J.Int(after, "paid"), AfterFree = after == null ? (int?)null : J.Int(after, "free"),
                Available = J.Bool(o, "available"), Block = J.Str(o, "block"), PityGain = J.Int(o, "pityGain"),
            };
        }
    }

    public sealed class ScoutOptions
    {
        public string BannerId, Name, Status, Notice;
        public bool PaidOnly, StepUp;
        public int WalletPaid, WalletFree;
        public List<ScoutWay> Ways = new List<ScoutWay>();
        /// <summary>The SR+ ticket while held (its own table, usable on no banner); null otherwise.</summary>
        public string SrPlusItemId, SrPlusName, SrPlusLine, SrPlusOddsPath;
        public int SrPlusOwned;
        public ScoutWay Way(string id) => Ways.Find(w => w.Id == id);
        public static ScoutOptions FromJson(string json) => Parse(JsonNode.Parse(json));
        internal static ScoutOptions Parse(JsonNode o)
        {
            var w = J.Opt(o, "wallet"); var sr = J.Opt(o, "srPlus");
            return new ScoutOptions
            {
                BannerId = J.Str(o, "bannerId"), Name = J.Str(o, "name"), Status = J.Str(o, "status"), Notice = J.Str(o, "notice"),
                PaidOnly = J.Bool(o, "paidOnly"), StepUp = J.Bool(o, "stepUp"), WalletPaid = J.Int(w, "paid"), WalletFree = J.Int(w, "free"),
                Ways = J.List(o, "ways", ScoutWay.Parse),
                SrPlusItemId = J.Str(sr, "itemId"), SrPlusName = J.Str(sr, "name"), SrPlusLine = J.Str(sr, "line"), SrPlusOddsPath = J.Str(sr, "oddsPath"), SrPlusOwned = J.Int(sr, "owned"),
            };
        }
    }

    public sealed partial class ApiClient
    {
        /// <summary>Quality pass 2: every way to pull on this banner now, with the exact paid / free split or the ticket (read only, player auth).</summary>
        public Task<ScoutOptions> GetScoutOptionsAsync(string bannerId, CancellationToken ct = default)
            => Call("GET", "/v1/gacha/" + Seg(bannerId) + "/options", null, true, null, true, ScoutOptions.Parse, ct);
    }
}
